-- Golden packet generated by the PINNED ORIGINAL TypeScript implementation.
-- The Lua table is generated from the exact same TS fixture, not hand-copied.
local Net=require("src.survev.net")
local Update=require("src.survev.update_msg")
local Registry=require("src.survev.type_registry")
local Decoder=require("src.survev.packet_decoder")
local expected,fixturePath=arg[1],arg[2]
assert(expected and fixturePath,"expected upstream fixture bytes and Lua table")
local msg=dofile(fixturePath)
setmetatable(msg,Update)

local packet=Net.newMsgStream(16384,Registry)
packet:serializeMsg(Net.MsgType.Update,msg)
local actual=(packet:getBuffer():gsub(".",function(c)
    return string.format("%02x",c:byte())
end))
assert(actual==expected,
    "Lua UpdateMsg differs from TypeScript.\nExpected: "..expected..
    "\nLua:      "..actual)

local incoming=Net.newMsgStream(packet:getBuffer(),Registry)
assert(incoming:deserializeMsgType()==Net.MsgType.Update)
local d=Update.new()
d:deserialize(incoming:getStream())
assert(d.flags==65535,"all 16 flags must be set")
assert(#d.fullObjects==11 and #d.partObjects==4)
assert(d.fullObjects[1].outfit=="outfitBase")
assert(d.fullObjects[1].frozen and #d.fullObjects[1].perks==1)
assert(d.fullObjects[2].isDoor and d.fullObjects[2].isButton)
assert(d.fullObjects[6].puzzle.errSeq==13)
assert(d.fullObjects[7].layerObjIds[2]==101)
assert(d.fullObjects[11].landed==true)
assert(d.partObjects[2].__id==11)
assert(d.activePlayerData.healthDirty)
assert(d.activePlayerData.inventory["9mm"]==87)
assert(d.activePlayerData.inventory["4xscope"]==1)
assert(d.activePlayerData.weapons[3].ammo==1)
assert(d.gasData.duration==38.5 and #d.playerInfos==1)
assert(d.playerStatus[1].role=="bandage")
assert(#d.bullets==1 and d.bullets[1].reflectCount==2)
assert(d.bullets[1].highVelocity)
assert(d.mapIndicators[1].id==3 and d.killLeaderId==10)
assert(d.ack==91)
local batch=Decoder.decode(packet:getBuffer())
assert(#batch==1 and batch[1].id==Net.MsgType.Update and batch[1].msg.ack==91)
assert(Update.getPlayerStatusUpdateRate(true)==.5)
assert(Update.getPlayerStatusUpdateRate(false)==.25)
print("UpdateMsg 16 flags / 11 objects: byte-identical to original and decoded")
